# Implementations of common RNGs for black-box matching.
class MT19937:
    def __init__(self, seed):
        self.mt=[0]*624; self.mt[0]=seed & 0xFFFFFFFF
        for i in range(1,624):
            self.mt[i]=(1812433253*(self.mt[i-1]^(self.mt[i-1]>>30))+i)&0xFFFFFFFF
        self.idx=624
    def gen(self):
        for i in range(624):
            y=(self.mt[i]&0x80000000)+(self.mt[(i+1)%624]&0x7fffffff)
            self.mt[i]=self.mt[(i+397)%624]^(y>>1)
            if y%2: self.mt[i]^=2567483615
        self.idx=0
    def __call__(self):
        if self.idx>=624: self.gen()
        y=self.mt[self.idx]; self.idx+=1
        y^=y>>11; y^=(y<<7)&2636928640; y^=(y<<15)&4022730752; y^=y>>18
        return y
    MIN=0; MAX=0xFFFFFFFF

class MT19937_64:
    def __init__(self, seed):
        self.mt=[0]*312; self.mt[0]=seed & ((1<<64)-1)
        for i in range(1,312):
            self.mt[i]=(6364136223846793005*(self.mt[i-1]^(self.mt[i-1]>>62))+i)&((1<<64)-1)
        self.idx=312
    def gen(self):
        UM=0xFFFFFFFF80000000; LM=0x7FFFFFFF
        mag=[0,0xB5026F5AA96619E9]
        for i in range(312):
            x=(self.mt[i]&UM)|(self.mt[(i+1)%312]&LM)
            self.mt[i]=self.mt[(i+156)%312]^(x>>1)^mag[x&1]
        self.idx=0
    def __call__(self):
        if self.idx>=312: self.gen()
        x=self.mt[self.idx]; self.idx+=1
        x^=(x>>29)&0x5555555555555555
        x^=(x<<17)&0x71D67FFFEDA60000
        x^=(x<<37)&0xFFF7EEE000000000
        x^=x>>43
        return x
    MIN=0; MAX=(1<<64)-1

class LCG:
    def __init__(self, seed, a, c, m, out=None):
        self.a=a; self.c=c; self.m=m
        s = seed % m
        if c==0 and s==0: s=1
        self.s=s; self.out=out
        self.MIN = 1 if c==0 else 0
        self.MAX = m-1
    def __call__(self):
        self.s=(self.a*self.s+self.c)%self.m
        return self.s if self.out is None else self.out(self.s)

def minstd0(seed): return LCG(seed,16807,0,2147483647)
def minstd(seed):  return LCG(seed,48271,0,2147483647)
def java(seed):
    class J:
        MIN=0; MAX=(1<<31)-1
        def __init__(self,sd): self.s=(sd^0x5DEECE66D)&((1<<48)-1)
        def __call__(self):
            self.s=(self.s*0x5DEECE66D+0xB)&((1<<48)-1)
            return self.s>>17
    return J(seed)

class GlibcRand:
    """glibc rand()/random() TYPE_3 (default)."""
    MIN=0; MAX=(1<<31)-1
    def __init__(self, seed):
        r=[0]*344
        r[0]=seed if seed else 1
        for i in range(1,31):
            r[i]=(16807*r[i-1])%2147483647
            if r[i]<0: r[i]+=2147483647
        for i in range(31,34): r[i]=r[i-31]
        for i in range(34,344): r[i]=(r[i-31]+r[i-3])&0xFFFFFFFF
